602 /// \returns true if all of the values in \p VL use the same opcode.
603 /// For comparison instructions, also checks if predicates match.
604 /// PoisonValues are considered matching.
605 /// Interchangeable instructions are not considered.
606 static bool allSameOpcode(ArrayRef<Value *> VL) {
607   auto *It = find_if(VL, IsaPred<Instruction>);
608   if (It == VL.end())
609     return true;
610   Instruction *MainOp = cast<Instruction>(*It);
611   unsigned Opcode = MainOp->getOpcode();
612   bool IsCmpOp = isa<CmpInst>(MainOp);
613   CmpInst::Predicate BasePred = IsCmpOp ? cast<CmpInst>(MainOp)->getPredicate()
614                                         : CmpInst::BAD_ICMP_PREDICATE;
615   return std::all_of(It, VL.end(), [&](Value *V) {
616     if (auto *CI = dyn_cast<CmpInst>(V))
617       return BasePred == CI->getPredicate();
618     if (auto *I = dyn_cast<Instruction>(V))
619       return I->getOpcode() == Opcode;
620     return isa<PoisonValue>(V);
621   });
622 }
