626 /// in the shuffle mask.
627 enum class UseMask {
628   FirstArg, ///< The mask is expected to be for permutation of 1-2 vectors,
629             ///< check for the mask elements for the first argument (mask
630             ///< indices are in range [0:VF)).
631   SecondArg, ///< The mask is expected to be for permutation of 2 vectors, check
