820 /// \returns True if Extract{Value,Element} instruction extracts element Idx.
821 static std::optional<unsigned> getExtractIndex(const Instruction *E) {
822   unsigned Opcode = E->getOpcode();
823   assert((Opcode == Instruction::ExtractElement ||
824           Opcode == Instruction::ExtractValue) &&
825          "Expected extractelement or extractvalue instruction.");
826   if (Opcode == Instruction::ExtractElement) {
827     auto *CI = dyn_cast<ConstantInt>(E->getOperand(1));
828     if (!CI)
829       return std::nullopt;
830     return CI->getZExtValue();
831   }
832   auto *EI = cast<ExtractValueInst>(E);
833   if (EI->getNumIndices() != 1)
834     return std::nullopt;
835   return *EI->idx_begin();
836 }
