1358 
1359     // Cannot combine poison and divisions.
1360     // TODO: do some smart analysis of the CallInsts to exclude divide-like
1361     // intrinsics/functions only.
1362     if (AnyPoison && (I->isIntDivRem() || I->isFPDivRem() || isa<CallInst>(I)))
