1364     unsigned InstOpcode = I->getOpcode();
1365     if (IsBinOp && isa<BinaryOperator>(I)) {
1366       if (BinOpHelper.add(I))
1367         continue;
1368     } else if (IsCastOp && isa<CastInst>(I)) {
1369       Value *Op0 = MainOp->getOperand(0);
1370       Type *Ty0 = Op0->getType();
1371       Value *Op1 = I->getOperand(0);
1372       Type *Ty1 = Op1->getType();
1373       if (Ty0 == Ty1) {
1374         if (InstOpcode == Opcode || InstOpcode == AltOpcode)
1375           continue;
1376         if (Opcode == AltOpcode) {
1377           assert(isValidForAlternation(Opcode) &&
1378                  isValidForAlternation(InstOpcode) &&
1379                  "Cast isn't safe for alternation, logic needs to be updated!");
