1381           AltOp = I;
1382           continue;
1383         }
1384       }
1385     } else if (auto *Inst = dyn_cast<CmpInst>(I); Inst && IsCmpOp) {
1386       auto *BaseInst = cast<CmpInst>(MainOp);
1387       Type *Ty0 = BaseInst->getOperand(0)->getType();
1388       Type *Ty1 = Inst->getOperand(0)->getType();
1389       if (Ty0 == Ty1) {
1390         assert(InstOpcode == Opcode && "Expected same CmpInst opcode.");
1391         assert(InstOpcode == AltOpcode &&
1392                "Alternate instructions are only supported by BinaryOperator "
1393                "and CastInst.");
1394         // Check for compatible operands. If the corresponding operands are not
