1396         CmpInst::Predicate CurrentPred = Inst->getPredicate();
1397         CmpInst::Predicate SwappedCurrentPred =
1398             CmpInst::getSwappedPredicate(CurrentPred);
1399 
1400         if ((VL.size() == 2 || SwappedPredsCompatible) &&
