18089         Align CommonAlignment = computeCommonAlignment<LoadInst>(E->Scalars);
18090         NewLI = Builder.CreateMaskedGather(VecTy, VecPtr, CommonAlignment);
18091       }
18092       Value *V = E->State == TreeEntry::CompressVectorize
18093                      ? NewLI
18094                      : ::propagateMetadata(NewLI, E->Scalars);
18095 
18096       V = FinalShuffle(V, E);
18097       E->VectorizedValue = V;
18098       ++NumVectorInstructions;
18099       return V;
18100     }
18101     case Instruction::Store: {
18102       auto *SI = cast<StoreInst>(VL0);
18103 
18104       setInsertPointAfterBundle(E);
18105 
18106       Value *VecValue = vectorizeOperand(E, 0);
18107       if (VecValue->getType() != VecTy)
18108         VecValue =
18109             Builder.CreateIntCast(VecValue, VecTy, GetOperandSignedness(0));
18110       VecValue = FinalShuffle(VecValue, E);
18111 
18112       Value *Ptr = SI->getPointerOperand();
18113       Instruction *ST;
18114       if (E->State == TreeEntry::Vectorize) {
18115         ST = Builder.CreateAlignedStore(VecValue, Ptr, SI->getAlign());
18116       } else {
18117         assert(E->State == TreeEntry::StridedVectorize &&
18118                "Expected either strided or consecutive stores.");
18119         if (!E->ReorderIndices.empty()) {
18120           SI = cast<StoreInst>(E->Scalars[E->ReorderIndices.front()]);
18121           Ptr = SI->getPointerOperand();
18122         }
18123         Align CommonAlignment = computeCommonAlignment<StoreInst>(E->Scalars);
18124         Type *StrideTy = DL->getIndexType(SI->getPointerOperandType());
18125         auto *Inst = Builder.CreateIntrinsic(
18126             Intrinsic::experimental_vp_strided_store,
18127             {VecTy, Ptr->getType(), StrideTy},
18128             {VecValue, Ptr,
18129              ConstantInt::get(
18130                  StrideTy, -static_cast<int>(DL->getTypeAllocSize(ScalarTy))),
18131              Builder.getAllOnesMask(VecTy->getElementCount()),
18132              Builder.getInt32(E->Scalars.size())});
18133         Inst->addParamAttr(
18134             /*ArgNo=*/1,
18135             Attribute::getWithAlignment(Inst->getContext(), CommonAlignment));
18136         ST = Inst;
18137       }
18138 
18139       Value *V = ::propagateMetadata(ST, E->Scalars);
18140 
18141       E->VectorizedValue = V;
18142       ++NumVectorInstructions;
18143       return V;
18144     }
18145     case Instruction::GetElementPtr: {
18146       auto *GEP0 = cast<GetElementPtrInst>(VL0);
18147       setInsertPointAfterBundle(E);
18148 
18149       Value *Op0 = vectorizeOperand(E, 0);
18150 
18151       SmallVector<Value *> OpVecs;
18152       for (int J = 1, N = GEP0->getNumOperands(); J < N; ++J) {
18153         Value *OpVec = vectorizeOperand(E, J);
18154         OpVecs.push_back(OpVec);
18155       }
18156 
18157       Value *V = Builder.CreateGEP(GEP0->getSourceElementType(), Op0, OpVecs);
18158       if (Instruction *I = dyn_cast<GetElementPtrInst>(V)) {
18159         SmallVector<Value *> GEPs;
18160         for (Value *V : E->Scalars) {
18161           if (isa<GetElementPtrInst>(V))
18162             GEPs.push_back(V);
18163         }
18164         V = ::propagateMetadata(I, GEPs);
18165       }
18166 
18167       V = FinalShuffle(V, E);
18168 
18169       E->VectorizedValue = V;
